<?php
namespace Dth\Crm\Filament\Resources;
use Dth\Crm\Filament\Resources\CompanyMatchCandidateResource\Pages; use Dth\Crm\Models\CompanyMatchCandidate; use Dth\Crm\Filament\Navigation\CrmNavigationGroup; use Dth\Crm\Support\StatusColor; use Dth\Crm\Services\CompanyMatchReviewService; use Filament\Resources\Resource; use Filament\Schemas\Schema; use Filament\Tables\Table; use Filament\Tables\Columns\TextColumn; use Filament\Actions; use Filament\Notifications\Notification;
class CompanyMatchCandidateResource extends Resource {protected static ?string $model=CompanyMatchCandidate::class;protected static string|\BackedEnum|null $navigationIcon='heroicon-o-link';protected static string|\UnitEnum|null $navigationGroup=CrmNavigationGroup::Crm;public static function getNavigationLabel():string{return \Dth\Crm\Support\UiText::get('navigation.match_candidates','Company matching',context:'navigation');}public static function canCreate():bool{return false;}public static function form(Schema $s):Schema{return $s;}public static function table(Table $t):Table{return $t->columns([TextColumn::make('submission_reference')->label('Submission'),TextColumn::make('contact.display_name')->label('Liên hệ'),TextColumn::make('suggestedCompany.legal_name')->label('Doanh nghiệp gợi ý'),TextColumn::make('matched_by')->label('Khớp bởi'),TextColumn::make('confidence')->suffix('%')->label('Độ tin cậy'),TextColumn::make('status')->badge()->color(fn($s)=>StatusColor::for($s))])->recordActions([Actions\Action::make('accept')->label('Chấp nhận')->visible(fn($r)=>$r->status==='pending')->action(function($r){app(CompanyMatchReviewService::class)->accept($r,auth()->id());Notification::make()->success()->title('Đã ghép doanh nghiệp')->send();}),Actions\Action::make('reject')->label('Từ chối')->color('danger')->visible(fn($r)=>$r->status==='pending')->action(fn($r)=>app(CompanyMatchReviewService::class)->reject($r,auth()->id())),Actions\ViewAction::make()]);}public static function getPages():array{return ['index'=>Pages\ListCompanyMatchCandidates::route('/'),'view'=>Pages\ViewCompanyMatchCandidate::route('/{record}')];}}
